import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"8、【比】 坤下坎上","description":"周易阐真 - 8、【比】 坤下坎上","frontmatter":{"title":"8、【比】 坤下坎上","description":"周易阐真 - 8、【比】 坤下坎上"},"headers":[],"relativePath":"zh/classics/chanzhen/009.md","filePath":"zh/classics/chanzhen/009.md"}'),s={name:"zh/classics/chanzhen/009.md"};function n(c,p,i,o,h,l){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：比，吉也；比，辅也，下顺从也。原筮，元永贞，无咎，以刚中也。不宁方来，上下应也。后夫凶，其道穷也。</p></blockquote><h1 id="_8、【比】-坤下坎上" tabindex="-1">8、【比】 坤下坎上 <a class="header-anchor" href="#_8、【比】-坤下坎上" aria-label="Permalink to “8、【比】 坤下坎上”">​</a></h1><p>初六：有孚，比之无咎。有孚盈缶，终来有它，吉。</p><p>六二：比之自内，贞吉。</p><p>六三：比之匪人。</p><p>六四：外比之，贞吉。</p><p>九五：显比。王用三驱，失前禽。邑人不诫，吉。</p><p>上六：比之无首，凶。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：地上有水，比。先王以建万国，亲诸侯。</p><p>比者，亲也。上坎水，下坤地，是地上有水，水所以滋润万物；水行地上，通流无阻，地无疆而水润亦无疆，此比之象也。</p><p>先王有见于此，知天下大矣，一人之施治有限，安得人人而亲之。以是建万国，封诸侯，兴朝觐之典，亲诸侯，使诸侯各亲其国，民于是施治。不能及者，而亦及之；远民不能亲者，而亦亲之。特以亲诸侯，即亲万民耳。修道者，明阴阳五行五德之理，使各居其位，如建国建诸侯也；使阴阳调和，五行一气，五德相合，如亲诸侯也；五行攒而五德合，万缘俱化，万善同归，如亲诸侯亲万民也。卦体坎中一阳，居于中正尊位，即道心耳。道心发现，仁义礼智根于心，万理纷纭，浑然天理，大地里黄芽长遍，满世界金花开绽，顺手拈来，俱是灵药，亦如水流地上，无处不通。先王亲诸侯，修道者亲万善，同一理也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>比者，彼此亲比相效之义。卦体一阳居于尊位，上下五阴，皆顺从之。又卦德顺以通险，故谓比。此以阴顺阳之卦，承上讼卦而来。讼者，阴不顺阳而陷阳，阴阳乖戾，五行相戕，贼害其真，故终凶。若知其凶，逆而修之，阴不陷阳而顺阳，阴阳相和，五行一气，性定命凝，此以邪比正，以假比真之道。比之吉者也。</p><p>比正比真之吉，莫贵乎比其原本。原本者，即坎宫所陷先天一点阳气，此气乃天一所生，名曰真一之精，又曰真一之水，又曰真一之气，乃生物之元气，在卦为原筮，在人为元仁。</p><p>原筮者，蓍策未分之时。元仁者，阴阳混成之真。但此元气，陷于阴中，为后天所蔽，易失难寻，非虚极静笃、心坚志远，而不能复还，故原筮元永贞，方能无咎也。</p><p>永贞则贞下起元，元气一复，阴气即顺，仍是当年无伤无损，浑然天理，一无所咎，囫囫囵囵之原本也。</p><p>《道德经》云：“致虚极，守静笃，万物并作，吾以观其复。”《沁园春》云：“七返还丹，在人先须炼己待时。”永贞之道，即致虚守静，炼己之功也。</p><p>盖炼己不熟，即我家真阴不现，致守不专，则他家真阳不来，欲伏西邻之情，先降东家之性。不宁方来，正所以炼己待时，以求其复耳。</p><p>不宁二字，其中有随时加减、防危虑险等等工程，正解永贞之义。我不宁而彼方来，所谓将欲取之，必先与之也。先与者，顺其所欲，以我而比他，所以取彼之欢心。后取者，诚能动物，他来而比我，所以盗彼之生气，先后分明，人我共济，还丹可结。否则，我不能先与，妄想彼来，宜先者反后，宜后者反先，颠倒其比，是名后天，所谓“凡俗欲求天上事，寻时须要世间财，若他少行多悭吝，千万神仙不肯来”，取凶必矣。焉能致吉成道乎?</p><p>初六，自卑自下，以柔比刚，是信于比而比之，即能无咎者。盖信于比，即能虚心，虚心即能实腹，不但有孚无咎，方且有孚盈缶，终来有他吉，必将比于至善之地矣。此信比而终吉者也。</p><p>六二，柔顺得中，未比于外，先比于内，是比之自内也。自内之比，炼己持心，随时采药，欲取于彼，不失于我。此内比之得正者也。</p><p>六三，性质本愚，又与小人为伍，以阴比阴，是比之匪人也。匪人之比，无益有损，何贵于比。此外比之不正者也。</p><p>六四，以柔比刚，见贤思齐焉，虽愚必明，虽柔必强。此外比之得正者也。</p><p>九五，刚健中正，阳气足而阴气自化，是显然之比也。显然之比，非有勉强，出于自然，犹如王者驱禽，四面而开一面，用三驱失前禽也。用三驱者，取真收顺也。失前禽者，舍假放逆也。取真舍假，真者来而假者自化。收顺放逆，顺者得而逆者自无。修道至于真假俱化，逆顺皆无，方寸之中，湛然常寂，至善无恶，杂念不生，如邑人不诚而自化。此内外一气之比者也。</p><p>上六，愚而自用，既不能内比，又不能外比，依一己之阴，随心造作，终无出头之日，是比之无首也。无首之比，空空一世，到老无成，自取其凶。此始终不知比人者也。</p><p>夫修真之事，以无道而比有道，以无德而比有德，总要真心实意，步步着力，期必道德归于中正而后已。道德中正，金丹入口，点化群阴，如猫捕鼠。</p><p>噫!采药时须用橐龠，炼己时还要真铅。若行比道，不知原筮之物，不识永贞之元，任性作为，不落于比之匪人，即归于比之无首，致咎取凶，势所必有，学者可不亲近真师乎?</p>',28)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
